#!/usr/bin/env python3

# ==========================================================
# Script   : historical_sparse_scheduler.py
# Purpose  : Retain an exploratory or secondary historical analysis for transparent provenance
# Inputs   : see data/README.md and config/paths.yml
# Outputs  : historical workspace outputs; not generated by run_all.sh
# Paper    : Not a final-results workflow entry point
# Seed     : see config/params.yml
# Runtime  : not benchmarked in the public release
# Last run : see provenance/source_provenance.csv
# Source   : guarded-workspace:scripts/run_v31_yellow_enet_scheduler.py
# ==========================================================
from __future__ import annotations
import argparse, concurrent.futures, hashlib, json, os, subprocess, time
from pathlib import Path

def atomic_json(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp-{os.getpid()}")
    tmp.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n")
    os.replace(tmp, path)

def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True); ap.add_argument("--contract", required=True)
    ap.add_argument("--slots", type=int, default=64)
    a = ap.parse_args(); repo = Path(a.repo).resolve(); contract = Path(a.contract).resolve()
    if "reback2" in repo.parts or not (1 <= a.slots <= 64): raise SystemExit("invalid repo/slots")
    root = repo / "agent_work" / "yellow_enet_nested_20261016"
    root.mkdir(parents=True, exist_ok=True); status = root / "SCHEDULER_STATUS.json"
    tasks = [f"R{r:02d}F{k}" for r in range(1, 21) for k in range(1, 6)]
    env = os.environ.copy()
    env.update({"OMP_NUM_THREADS":"1", "OPENBLAS_NUM_THREADS":"1", "MKL_NUM_THREADS":"1", "BLIS_NUM_THREADS":"1", "VECLIB_MAXIMUM_THREADS":"1"})
    def done(t: str) -> bool:
        p = root / "workers" / t / "TASK_RECEIPT.json"
        if not p.exists(): return False
        try: return json.loads(p.read_text()).get("status") == "PASS"
        except Exception: return False
    def run(t: str) -> tuple[str,int]:
        d = root / "workers" / t; d.mkdir(parents=True, exist_ok=True)
        log = d / "worker.log"
        with log.open("w") as h:
            p = subprocess.run(["/opt/R/4.4.1/bin/Rscript", str(repo / "scripts" / "run_v31_historical_yellow_elastic_net.R"), "task", str(contract), t], cwd=repo, env=env, stdout=h, stderr=subprocess.STDOUT)
        return t, p.returncode
    pending = [t for t in tasks if not done(t)]
    atomic_json(status, {"state":"RUNNING", "slots":a.slots, "total":100, "completed":100-len(pending), "pending":len(pending), "started_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())})
    failures=[]
    with concurrent.futures.ThreadPoolExecutor(max_workers=a.slots) as ex:
        futs={ex.submit(run,t):t for t in pending}
        for f in concurrent.futures.as_completed(futs):
            t,rc=f.result()
            if rc != 0 or not done(t): failures.append(t)
            complete=sum(done(x) for x in tasks)
            atomic_json(status,{"state":"RUNNING" if not failures else "FAIL_CLOSED", "slots":a.slots, "total":100, "completed":complete, "failures":sorted(failures), "updated_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())})
    if failures:
        atomic_json(status,{"state":"FAILED", "total":100, "completed":sum(done(x) for x in tasks), "failures":sorted(failures)})
        return 2
    log = root / "aggregate.log"
    with log.open("w") as h:
        p=subprocess.run(["/opt/R/4.4.1/bin/Rscript",str(repo/"scripts"/"run_v31_historical_yellow_elastic_net.R"),"aggregate",str(contract)],cwd=repo,env=env,stdout=h,stderr=subprocess.STDOUT)
    state="COMPLETED" if p.returncode==0 else "AGGREGATE_FAILED"
    atomic_json(status,{"state":state,"slots":a.slots,"total":100,"completed":100,"aggregate_returncode":p.returncode,"finished_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())})
    return p.returncode

if __name__ == "__main__": raise SystemExit(main())
